        // ---- test_legacy_data_dir.py

        private static (MindEnv env, List<string> log, LogSink sink) Share(TempDir t, bool windows = false)
        {
            var vars = new Dictionary<string, string>();
            vars[windows ? "LOCALAPPDATA" : "XDG_DATA_HOME"] = t.Path;
            var log = new List<string>();
            return (Env(vars, windows), log, (lvl, name, msg) => log.Add(msg));
        }

        [Fact]
        public void MovesOldFolderWhenNewIsMissing()
        {
            using var t = new TempDir();
            var (env, _, sink) = Share(t);
            string old = t.Combine("hermesvoice-agent");
            Directory.CreateDirectory(Path.Combine(old, "logs"));
            File.WriteAllText(Path.Combine(old, "memory.db"), "m");
            string nw = MindConfig.DefaultDataDir(env);
            Assert.Equal("moved", MindConfig.MigrateLegacyDataDir(nw, env, sink));
            Assert.Equal("m", File.ReadAllText(Path.Combine(nw, "memory.db")));
            Assert.True(Directory.Exists(Path.Combine(nw, "logs")));
            Assert.False(Directory.Exists(old));
        }

        [Fact]
        public void BothExistLeavesBoth()
        {
            using var t = new TempDir();
            var (env, log, sink) = Share(t);
            string old = t.Combine("hermesvoice-agent"); Directory.CreateDirectory(old); File.WriteAllText(Path.Combine(old, "a"), "old");
            string nw = t.Combine("rimworldllm-agent"); Directory.CreateDirectory(nw); File.WriteAllText(Path.Combine(nw, "a"), "new");
            Assert.Equal("both", MindConfig.MigrateLegacyDataDir(nw, env, sink));
            Assert.Equal("old", File.ReadAllText(Path.Combine(old, "a")));
            Assert.Equal("new", File.ReadAllText(Path.Combine(nw, "a")));
            Assert.Single(log, m => m.Contains("both"));
        }

