        // ---- test_creative.py::test_config_accepts_lists_for_per_kind_fields

        [Fact]
        public void ConfigAcceptsListsForPerKindFields()
        {
            using var t = new TempDir();
            string p = t.Combine("c.json");
            File.WriteAllText(p, "{\"creative_ground_for\": [\"art\", \"lore\"], \"creative_plan_for\": [\"recap\"], \"creative_best_of_for\": [\"art\"]}");
            var c = MindConfig.Load(p, Env(new()));
            Assert.Equal(new[] { "art", "lore" }, c.CreativeGroundFor);
            Assert.Equal(new[] { "art" }, c.CreativeBestOfFor);
            Assert.Equal(4, c.CreativeBestOfN);
            Assert.Equal(new[] { "recap" }, c.CreativePlanFor);
            Assert.Equal(new[] { "recap" }, c.CreativeFor("plan"));
            Assert.Equal(new[] { "art" }, c.CreativeFor("best_of"));
            Assert.Empty(c.CreativeFor("nope"));
            string tp = t.Combine("c.toml");
            File.WriteAllText(tp, "creative_ground_for = [\"vow\"]\n");
            Assert.Equal(new[] { "vow" }, MindConfig.Load(tp, Env(new())).CreativeGroundFor);
        }

