        [Fact]
        public void FileValuesAreCoercedLikePydanticAndUnknownKeysIgnored()
        {
            using var t = new TempDir();
            string p = t.Combine("c.toml");
            File.WriteAllText(p, "windows = 3\nunknown_key = 1\nnarrator_min_gap_real_s = 90\n[llm]\ntemperature = 1\nengine = true\n[quotas]\nactor_per_day = 7\n");
            var c = MindConfig.Load(p, Env(new() { ["RIMWORLDLLM_WINDOWS"] = "4" }));
            Assert.Equal(4, c.Windows);                  // the environment beats the file
            Assert.Equal(90.0, c.NarratorMinGapRealS);
            Assert.Equal(1.0, c.Llm.Temperature);
            Assert.True(c.Llm.Engine);
            Assert.Equal(7, c.Quotas.ActorPerDay);
            Assert.Throws<ConfigError>(() => MindConfig.Load(null, Env(new() { ["RIMWORLDLLM_WINDOWS"] = "many" })));
            File.WriteAllText(p, "windows = 2.5\n");
            Assert.Throws<ConfigError>(() => MindConfig.Load(p, Env(new())));
        }

